### Diff algorithm (LCS)

```go
func diffLines(a, b []string) []edit {
	n, m := len(a), len(b)
	// dp[i][j] = length of LCS of a[i:], b[j:]
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if a[i] == b[j] {
				dp[i][j] = dp[i+1][j+1] + 1
			} else if dp[i+1][j] >= dp[i][j+1] {
				dp[i][j] = dp[i+1][j]
			} else {
				dp[i][j] = dp[i][j+1]
			}
		}
	}
	var edits []edit
	i, j := 0, 0
	for i < n && j < m {
		switch {
		case a[i] == b[j]:
			edits = append(edits, edit{opEqual, a[i]})
			i++
			j++
		case dp[i+1][j] >= dp[i][j+1]:
			edits = append(edits, edit{opDelete, a[i]})
			i++
		default:
			edits = append(edits, edit{opInsert, b[j]})
			j++
		}
	}
	for ; i < n; i++ {
		edits = append(edits, edit{opDelete, a[i]})
	}
	for ; j < m; j++ {
		edits = append(edits, edit{opInsert, b[j]})
	}
	return edits
}
```

