```go
// Package unified computes and formats unified diffs between two pieces of text.
package unified

import (
	"fmt"
	"strconv"
	"strings"
)

// DefaultContext is the number of unchanged lines shown around each change.
const DefaultContext = 3

type op int

const (
	opEqual op = iota
	opDelete
	opInsert
)

type edit struct {
	op   op
	line string
}

// Diff returns the unified diff between old and new using the default
// amount of context. It returns an empty string when the inputs are equal.
func Diff(old, new string) string {
	return DiffContext(old, new, DefaultContext)
}

// DiffContext is like Diff but controls how many lines of surrounding
// context are included with each change.
func DiffContext(old, new string, context int) string {
	if context < 0 {
		context = 0
	}
	edits := diffLines(splitLines(old), splitLines(new))
	hunks := buildHunks(edits, context)
	if len(hunks) == 0 {
		return ""
	}
	var b strings.Builder
	oldLine, newLine := lineNumbers(edits, hunks)
	for i, h := range hunks {
		writeHunkHeader(&b, h, oldLine[i], newLine[i])
		for _, e := range h.edits {
			writeEdit(&b, e)
		}
	}
	return b.String()
}
```

