```go
func buildHunks(edits []edit, context int) []hunk {
	var changes []int
	for i, e := range edits {
		if e.op != opEqual {
			changes = append(changes, i)
		}
	}
	if len(changes) == 0 {
		return nil
	}
	oldPrefix := make([]int, len(edits)+1)
	newPrefix := make([]int, len(edits)+1)
	for i, e := range edits {
		oldPrefix[i+1] = oldPrefix[i]
		newPrefix[i+1] = newPrefix[i]
		if e.op != opInsert {
			oldPrefix[i+1]++
		}
		if e.op != opDelete {
			newPrefix[i+1]++
		}
	}
	var hunks []hunk
	groupStart := changes[0]
	prev := changes[0]
	flush := func(last int) {
		s := groupStart - context
		if s < 0 { s = 0 }
		e := last + context + 1
		if e > len(edits) { e = len(edits) }
		h := hunk{s: s, e: e, edits: edits[s:e]}
		h.oldCount = oldPrefix[e] - oldPrefix[s]
		h.newCount = newPrefix[e] - newPrefix[s]
		h.oldStart = oldPrefix[s] + 1
		if h.oldCount == 0 { h.oldStart = oldPrefix[s] }
		h.newStart = newPrefix[s] + 1
		if h.newCount == 0 { h.newStart = newPrefix[s] }
		hunks = append(hunks, h)
	}
	for _, c := range changes[1:] {
		if c-prev-1 <= 2*context { // equal lines between changes
			prev = c
			continue
		}
		flush(prev)
		groupStart = c
		prev = c
	}
	flush(prev)
	return hunks
}
```

