```go
func normalize(edits []edit) []edit {
	out := make([]edit, 0, len(edits))
	for i := 0; i < len(edits); {
		if edits[i].op == opEqual {
			out = append(out, edits[i]); i++; continue
		}
		j := i
		var dels, inss []edit
		for j < len(edits) && edits[j].op != opEqual {
			if edits[j].op == opDelete { dels = append(dels, edits[j]) } else { inss = append(inss, edits[j]) }
			j++
		}
		out = append(out, dels...)
		out = append(out, inss...)
		i = j
	}
	return out
}
```

